import React, { useCallback } from 'react';

import { useNumberSpinButtonContext } from './useNumberSpinButtonContext.js';
import { useValidateAndSanitize } from './useValidateAndSanitize.js';
import { useSelection } from '../../hooks/useSelection.js';
import type { _NumberSpinButtonProps } from '../types.js';

/**
 * This hook provides a keydown handler to navigate a given value range.
 */
export const useValueNavigation = (
  ref: React.RefObject<HTMLElement>,
  props: _NumberSpinButtonProps,
) => {
  const { disabled, readonly, onChange } = props;
  const { value, minValue, maxValue, applyText, smallStep, bigStep } =
    useNumberSpinButtonContext();
  const { selectAll } = useSelection(ref);
  const { sanitize, format } = useValidateAndSanitize(props);

  // Default transformer functions for spinbutton keyboard handlers
  const {
    onArrowUp = (value, e) => {
      e.preventDefault();
      return (value ?? 0) + smallStep;
    },
    onArrowDown = (value, e) => {
      e.preventDefault();
      return (value ?? 0) - smallStep;
    },
    onPageUp = (value, e) => {
      e.preventDefault();
      return (value ?? 0) + bigStep;
    },
    onPageDown = (value, e) => {
      e.preventDefault();
      return (value ?? 0) - bigStep;
    },
    onHome = (value, e) => {
      // Only execute if a minValue prop was defined
      if (props.minValue !== undefined) {
        e.preventDefault();
        return minValue;
      }
      return value;
    },
    onEnd = (value, e) => {
      // Only execute if a maxValue prop was defined
      if (props.maxValue !== undefined) {
        e.preventDefault();
        return maxValue;
      }
      return value;
    },
  } = props;

  const keyDownHandler = useCallback(
    (e: React.KeyboardEvent) => {
      if (disabled || readonly) {
        // Prevent any value changes via keys, but don't prevent the default behavior.
        return;
      }

      // Ensures, the given value is always sanitized before updating the inner state.
      const updateValue = (newValue: number | null) => {
        const sanitizedValue = sanitize(newValue);
        if (value === sanitizedValue) {
          return;
        }

        const newText = format(sanitizedValue);
        applyText(newText, ref.current);
        onChange?.(sanitizedValue);
        selectAll();
      };

      switch (e.key) {
        case 'ArrowUp':
          updateValue(onArrowUp(value, e));
          break;
        case 'ArrowDown':
          updateValue(onArrowDown(value, e));
          break;
        case 'PageUp':
          updateValue(onPageUp(value, e));
          break;
        case 'PageDown':
          updateValue(onPageDown(value, e));
          break;
        case 'Home':
          updateValue(onHome(value, e));
          break;
        case 'End':
          updateValue(onEnd(value, e));
          break;
      }
    },
    [
      disabled,
      readonly,
      value,
      format,
      sanitize,
      applyText,
      ref,
      onChange,
      selectAll,
      onArrowUp,
      onArrowDown,
      onPageUp,
      onPageDown,
      onHome,
      onEnd,
    ],
  );
  return { keyDownHandler };
};
